from collections.abc import Callable, Iterator

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.post("/items", response_model=schemas.ItemRead, status_code=201)
    def create(
        payload: schemas.ItemCreate, db: Session = Depends(get_session)
    ) -> models.Item:
        row = models.Item(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/items" + "/{item_id}", response_model=schemas.ItemRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Item:
        row = db.get(models.Item, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    @router.get("/items", response_model=list[schemas.ItemRead])
    def list_items(db: Session = Depends(get_session)) -> list[models.Item]:
        return list(db.scalars(select(models.Item).order_by(models.Item.id)))

    @router.patch("/items" + "/{item_id}", response_model=schemas.ItemRead)
    def patch(
        item_id: int, payload: schemas.ItemPatch, db: Session = Depends(get_session)
    ) -> models.Item:
        row = db.get(models.Item, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.delete("/items" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Item, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    return router
